{
  "bioavailability_prediction": "low",
  "claims": [
    {
      "card_ids": ["C07"],
      "claim": "Lycopene, a highly lipophilic C40 isoprenoid, showed only ~2.6% systemic availability after oral capsule dosing, supporting that large polyprenyl lipids are generally poorly absorbed.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C19"],
      "claim": "Tocotrienol, which combines a polar chromanol head with an isoprenoid tail, was reported to have poor oral bioavailability, providing a closer structural analogy to the ubiquinone/polyprenyl query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C20"],
      "claim": "A 13C-lycopene study reported 23.2±8% bioavailability for all-trans lycopene, a contradictory example showing that some highly lipophilic isoprenoids can exceed 20% under certain conditions.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C21"],
      "claim": "Phytoene, another C40 isoprenoid, was estimated at 58% bioavailability in a compartmental model, but this is a single modeling-based estimate with limited directness to the much larger ubiquinone.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C14"],
      "claim": "Hyperforin, a polyprenylated natural product, was reported to have high oral bioavailability, but its lower molecular weight and different polar core limit transferability to the query.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "Predicted low. The query is a very large, highly lipophilic polyprenyl benzoquinone (CoQ-type). The most transferable experimental analogues—lycopene and tocotrienol—show low oral bioavailability, and the extreme MW/logP/solubility liabilities support F<20%. Contradictory high estimates for phytoene and hyperforin are less transferable or model-based and do not outweigh the direct lipophilic-isoprenoid low-bioavailability evidence.",
  "evidence_gaps": [
    "No direct absolute oral bioavailability record for ubiquinone/CoQ10 or the exact query molecule.",
    "Lycopene and phytoene bioavailability estimates are formulation- and model-dependent, making true absolute F uncertain.",
    "No data on whether the query would be administered in a solubilized or lipid-based formulation, which can markedly alter absorption.",
    "First-pass metabolism, intestinal efflux, and lymphatic absorption contributions are not directly measured."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

